pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrancy_bonus} from "../src/Reentrancy_bonus.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrancy_bonus c;

    function setUp() public {
        c = new Reentrancy_bonus();
    }

    function _run(address r) internal {
        uint b0 = address(c).balance;
        vm.assume(b0 >= 200);
        try c.getFirstWithdrawalBonus(r) {} catch { return; }
        try c.withdrawReward(r) {} catch { return; }
        assertTrue(address(c).balance == b0 - 100);
    }

    function testFuzz_run(address r) public {
        vm.assume(r.code.length == 0 && uint160(r) > 0xffff && r != address(this) && r != address(c) && r != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && r != 0x000000000000000000636F6e736F6c652e6c6f67 && r != 0x4e59b44847b379578588920cA78FbF26c0B4956C && r != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(r);
    }

    receive() external payable {}
}
